ALTER TABLE public.financeiro_cadastros ADD COLUMN responsavel_cpf_cnpj text, ADD COLUMN responsavel_email text, ADD COLUMN responsavel_cep text, ADD COLUMN responsavel_logradouro text, ADD COLUMN responsavel_numero text, ADD COLUMN responsavel_complemento text, ADD COLUMN responsavel_bairro text, ADD COLUMN responsavel_cidade text, ADD COLUMN responsavel_uf text, ADD COLUMN gateway_cliente_id text;
ALTER TABLE public.financeiro_config ADD COLUMN gateway_ambiente text NOT NULL DEFAULT 'sandbox' CHECK(gateway_ambiente IN ('sandbox','producao')), ADD COLUMN gateway_ativo boolean NOT NULL DEFAULT false, ADD COLUMN mensagem_fatura text NOT NULL DEFAULT 'Olá, {responsavel}. A fatura de {residentes}, no valor de {valor}, vence em {vencimento}. Pague pelo link: {link}';
CREATE TABLE public.financeiro_faturas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pagador_nome text NOT NULL, pagador_cpf_cnpj text NOT NULL, gateway_cliente_id text, gateway_cobranca_id text, forma text NOT NULL CHECK(forma IN ('boleto','pix','boleto_pix')), valor_centavos bigint NOT NULL CHECK(valor_centavos>0), vencimento date NOT NULL, status text NOT NULL DEFAULT 'aguardando' CHECK(status IN ('aguardando','paga','vencida','cancelada','estornada')), link text, linha_digitavel text, pix_copia_cola text, valor_recebido_centavos bigint, tarifa_centavos bigint, data_pagamento date, observacoes text NOT NULL DEFAULT '', criado_por uuid, criado_em timestamptz NOT NULL DEFAULT now(), atualizado_em timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX financeiro_faturas_gateway ON public.financeiro_faturas(gateway_cobranca_id) WHERE gateway_cobranca_id IS NOT NULL;
REVOKE ALL ON TABLE public.financeiro_faturas FROM anon, authenticated; GRANT SELECT ON public.financeiro_faturas TO authenticated; GRANT ALL ON public.financeiro_faturas TO service_role;
ALTER TABLE public.financeiro_faturas ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_faturas_read ON public.financeiro_faturas FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_fatura_cobrancas (fatura_id uuid NOT NULL REFERENCES public.financeiro_faturas(id), cobranca_id uuid NOT NULL REFERENCES public.financeiro_cobrancas(id), PRIMARY KEY(fatura_id,cobranca_id));
REVOKE ALL ON TABLE public.financeiro_fatura_cobrancas FROM anon, authenticated; GRANT SELECT ON public.financeiro_fatura_cobrancas TO authenticated; GRANT ALL ON public.financeiro_fatura_cobrancas TO service_role;
ALTER TABLE public.financeiro_fatura_cobrancas ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_fatura_cobrancas_read ON public.financeiro_fatura_cobrancas FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_gateway_eventos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evento_id text NOT NULL UNIQUE, tipo text NOT NULL, payload jsonb NOT NULL, processado boolean NOT NULL DEFAULT false, erro text, criado_em timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON TABLE public.financeiro_gateway_eventos FROM anon, authenticated; GRANT SELECT ON public.financeiro_gateway_eventos TO authenticated; GRANT ALL ON public.financeiro_gateway_eventos TO service_role;
ALTER TABLE public.financeiro_gateway_eventos ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_gateway_eventos_read ON public.financeiro_gateway_eventos FOR SELECT TO authenticated USING(private.financeiro_autorizado());
ALTER TABLE public.financeiro_pagamentos ADD COLUMN fatura_id uuid REFERENCES public.financeiro_faturas(id);
CREATE TRIGGER financeiro_auditoria AFTER INSERT OR UPDATE OR DELETE ON public.financeiro_faturas FOR EACH ROW EXECUTE FUNCTION private.financeiro_auditar();
CREATE FUNCTION private.financeiro_travar_fatura() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF (NEW.valor_centavos IS DISTINCT FROM OLD.valor_centavos OR NEW.ajuste_centavos IS DISTINCT FROM OLD.ajuste_centavos OR NEW.cancelada IS DISTINCT FROM OLD.cancelada) AND EXISTS(SELECT 1 FROM public.financeiro_fatura_cobrancas fc JOIN public.financeiro_faturas f ON f.id=fc.fatura_id WHERE fc.cobranca_id=NEW.id AND f.status IN ('aguardando','vencida')) THEN RAISE EXCEPTION 'Cobrança incluída em fatura ativa. Cancele a fatura antes de alterar o valor.'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER financeiro_travar_fatura BEFORE UPDATE ON public.financeiro_cobrancas FOR EACH ROW EXECUTE FUNCTION private.financeiro_travar_fatura();
CREATE FUNCTION private.financeiro_fatura_baixar(_fatura uuid,_data date,_valor bigint,_forma text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE f public.financeiro_faturas; rid uuid; x record; s jsonb; restante bigint; maximo bigint; pm bigint; pj bigint; pc bigint; pp bigint; pid uuid; total_rid bigint; lista jsonb='[]'; BEGIN SELECT * INTO f FROM public.financeiro_faturas WHERE id=_fatura FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Fatura não encontrada'; END IF; restante=_valor; FOR x IN SELECT c.id AS cobranca_id, c.residente_id, (private.financeiro_saldo(c.id,_data)->>'saldo')::bigint AS saldo FROM public.financeiro_fatura_cobrancas fc JOIN public.financeiro_cobrancas c ON c.id=fc.cobranca_id WHERE fc.fatura_id=_fatura AND NOT c.cancelada ORDER BY c.residente_id, c.vencimento, c.criado_em LOOP EXIT WHEN restante<=0; maximo=least(restante,x.saldo); IF maximo<=0 THEN CONTINUE; END IF; lista=lista||jsonb_build_object('residente',x.residente_id,'cobranca',x.cobranca_id,'valor',maximo); restante=restante-maximo; END LOOP; FOR rid IN SELECT DISTINCT (e->>'residente')::uuid FROM jsonb_array_elements(lista) e LOOP SELECT coalesce(sum((e->>'valor')::bigint),0) INTO total_rid FROM jsonb_array_elements(lista) e WHERE (e->>'residente')::uuid=rid; IF total_rid<=0 THEN CONTINUE; END IF; pid=gen_random_uuid(); INSERT INTO public.financeiro_pagamentos(id,residente_id,data,valor_centavos,forma,observacoes,fatura_id,criado_por) VALUES(pid,rid,_data,total_rid,_forma,'Recebimento automático via gateway',_fatura,auth.uid()); FOR x IN SELECT (e->>'cobranca')::uuid AS cobranca_id,(e->>'valor')::bigint AS valor FROM jsonb_array_elements(lista) e WHERE (e->>'residente')::uuid=rid LOOP s=private.financeiro_saldo(x.cobranca_id,_data); maximo=x.valor; pm=least(maximo,(s->>'multa')::bigint);maximo=maximo-pm; pj=least(maximo,(s->>'juros')::bigint);maximo=maximo-pj; pc=least(maximo,(s->>'correcao')::bigint);maximo=maximo-pc; pp=maximo; INSERT INTO public.financeiro_alocacoes(pagamento_id,cobranca_id,principal_centavos,multa_centavos,juros_centavos,correcao_centavos) VALUES(pid,x.cobranca_id,pp,pm,pj,pc); END LOOP; END LOOP; UPDATE public.financeiro_faturas SET valor_recebido_centavos=coalesce(valor_recebido_centavos,0)+_valor, data_pagamento=_data, status=CASE WHEN coalesce(valor_recebido_centavos,0)+_valor>=valor_centavos THEN 'paga' ELSE status END, atualizado_em=now() WHERE id=_fatura; END; $$;
CREATE FUNCTION public.financeiro_fatura_operar(_acao text,_dados jsonb,_operacao uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE f public.financeiro_faturas; id uuid; motivo text; res jsonb='{}'; chave text; admin boolean; BEGIN IF NOT private.financeiro_autorizado() THEN RAISE EXCEPTION 'Acesso financeiro não autorizado'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_operacao::text,0)); SELECT resposta INTO res FROM public.financeiro_operacoes WHERE id=_operacao AND usuario_id=auth.uid() AND acao='fatura_'||_acao; IF FOUND THEN RETURN res; END IF; res='{}'; SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') INTO admin; IF _acao='registrar' THEN id=coalesce(nullif(_dados->>'id','')::uuid,gen_random_uuid()); IF jsonb_array_length(coalesce(_dados->'cobrancas','[]'::jsonb))=0 THEN RAISE EXCEPTION 'Selecione ao menos uma cobrança'; END IF; FOR chave IN SELECT jsonb_array_elements_text(_dados->'cobrancas') LOOP IF NOT EXISTS(SELECT 1 FROM public.financeiro_cobrancas c WHERE c.id=chave::uuid AND NOT c.cancelada) THEN RAISE EXCEPTION 'Cobrança inválida ou cancelada'; END IF; IF EXISTS(SELECT 1 FROM public.financeiro_fatura_cobrancas fc JOIN public.financeiro_faturas fa ON fa.id=fc.fatura_id WHERE fc.cobranca_id=chave::uuid AND fa.status IN ('aguardando','vencida')) THEN RAISE EXCEPTION 'Uma das cobranças já está em uma fatura ativa'; END IF; END LOOP; INSERT INTO public.financeiro_faturas(id,pagador_nome,pagador_cpf_cnpj,gateway_cliente_id,gateway_cobranca_id,forma,valor_centavos,vencimento,link,linha_digitavel,pix_copia_cola,criado_por) VALUES(id,_dados->>'pagador_nome',_dados->>'pagador_cpf_cnpj',nullif(_dados->>'gateway_cliente_id',''),nullif(_dados->>'gateway_cobranca_id',''),_dados->>'forma',(_dados->>'valor_centavos')::bigint,(_dados->>'vencimento')::date,nullif(_dados->>'link',''),nullif(_dados->>'linha_digitavel',''),nullif(_dados->>'pix_copia_cola',''),auth.uid()); INSERT INTO public.financeiro_fatura_cobrancas(fatura_id,cobranca_id) SELECT id,(jsonb_array_elements_text(_dados->'cobrancas'))::uuid; res=jsonb_build_object('id',id); ELSIF _acao='cancelar' THEN motivo=trim(coalesce(_dados->>'motivo','')); IF motivo='' THEN RAISE EXCEPTION 'Informe o motivo'; END IF; SELECT * INTO STRICT f FROM public.financeiro_faturas WHERE id=(_dados->>'id')::uuid FOR UPDATE; IF f.status NOT IN ('aguardando','vencida') THEN RAISE EXCEPTION 'Fatura não pode ser cancelada nesta situação'; END IF; IF EXISTS(SELECT 1 FROM public.financeiro_pagamentos WHERE fatura_id=f.id AND NOT estornado) THEN RAISE EXCEPTION 'Fatura com recebimentos: estorne antes de cancelar'; END IF; UPDATE public.financeiro_faturas SET status='cancelada',observacoes=observacoes||E'\nCancelada: '||motivo,atualizado_em=now() WHERE id=f.id; ELSIF _acao='sincronizar' THEN SELECT * INTO STRICT f FROM public.financeiro_faturas WHERE id=(_dados->>'id')::uuid FOR UPDATE; UPDATE public.financeiro_faturas SET link=coalesce(nullif(_dados->>'link',''),link),linha_digitavel=coalesce(nullif(_dados->>'linha_digitavel',''),linha_digitavel),pix_copia_cola=coalesce(nullif(_dados->>'pix_copia_cola',''),pix_copia_cola),tarifa_centavos=coalesce(nullif(_dados->>'tarifa_centavos','')::bigint,tarifa_centavos),atualizado_em=now() WHERE id=f.id; IF _dados->>'situacao'='recebida' AND f.status IN ('aguardando','vencida') THEN PERFORM private.financeiro_fatura_baixar(f.id,coalesce(nullif(_dados->>'data_pagamento','')::date,(now() AT TIME ZONE 'America/Sao_Paulo')::date),(_dados->>'valor_recebido_centavos')::bigint,CASE WHEN f.forma='pix' THEN 'pix' ELSE 'boleto' END); ELSIF _dados->>'situacao'='vencida' AND f.status='aguardando' THEN UPDATE public.financeiro_faturas SET status='vencida',atualizado_em=now() WHERE id=f.id; ELSIF _dados->>'situacao'='cancelada' AND f.status IN ('aguardando','vencida') THEN UPDATE public.financeiro_faturas SET status='cancelada',observacoes=observacoes||E'\nCancelada no gateway',atualizado_em=now() WHERE id=f.id; ELSIF _dados->>'situacao'='estornada' THEN UPDATE public.financeiro_pagamentos SET estornado=true,motivo_estorno='Estorno registrado pelo gateway' WHERE fatura_id=f.id AND NOT estornado; UPDATE public.financeiro_faturas SET status='estornada',atualizado_em=now() WHERE id=f.id; END IF; ELSIF _acao='config_gateway' THEN IF NOT admin THEN RAISE EXCEPTION 'Somente administradores configuram o gateway de pagamentos'; END IF; UPDATE public.financeiro_config SET gateway_ambiente=coalesce(nullif(_dados->>'gateway_ambiente',''),gateway_ambiente),gateway_ativo=coalesce((_dados->>'gateway_ativo')::boolean,gateway_ativo),mensagem_fatura=coalesce(nullif(_dados->>'mensagem_fatura',''),mensagem_fatura),atualizado_em=now() WHERE id; ELSE RAISE EXCEPTION 'Operação de fatura desconhecida'; END IF; INSERT INTO public.financeiro_operacoes(id,usuario_id,acao,resposta) VALUES(_operacao,auth.uid(),'fatura_'||_acao,res); RETURN res; END; $$;
REVOKE ALL ON FUNCTION public.financeiro_fatura_operar(text,jsonb,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.financeiro_fatura_operar(text,jsonb,uuid) TO authenticated;
CREATE FUNCTION public.financeiro_webhook_processar(_evento_id text,_tipo text,_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE f public.financeiro_faturas; p jsonb; v bigint; d date; forma text; tarifa bigint; BEGIN INSERT INTO public.financeiro_gateway_eventos(evento_id,tipo,payload) VALUES(_evento_id,_tipo,_payload) ON CONFLICT(evento_id) DO NOTHING; IF NOT FOUND THEN RETURN jsonb_build_object('duplicado',true); END IF; p=_payload->'payment'; IF p IS NULL THEN UPDATE public.financeiro_gateway_eventos SET processado=true,erro='Evento sem dados de pagamento' WHERE evento_id=_evento_id; RETURN jsonb_build_object('ignorado',true); END IF; SELECT * INTO f FROM public.financeiro_faturas WHERE gateway_cobranca_id=p->>'id' FOR UPDATE; IF NOT FOUND THEN UPDATE public.financeiro_gateway_eventos SET processado=true,erro='Fatura não encontrada para a cobrança do gateway' WHERE evento_id=_evento_id; RETURN jsonb_build_object('ignorado',true); END IF; IF _tipo IN ('PAYMENT_RECEIVED','PAYMENT_CONFIRMED') THEN v=round(coalesce(nullif(p->>'value','')::numeric,0)*100); d=coalesce(nullif(p->>'paymentDate','')::date,nullif(p->>'confirmedDate','')::date,(now() AT TIME ZONE 'America/Sao_Paulo')::date); forma=CASE WHEN p->>'billingType'='PIX' THEN 'pix' ELSE 'boleto' END; tarifa=greatest(0,v-round(coalesce(nullif(p->>'netValue','')::numeric,0)*100)); PERFORM private.financeiro_fatura_baixar(f.id,d,v,forma); UPDATE public.financeiro_faturas SET tarifa_centavos=tarifa,link=coalesce(p->>'invoiceUrl',link),linha_digitavel=coalesce(p->>'identificationField',linha_digitavel),atualizado_em=now() WHERE id=f.id; ELSIF _tipo='PAYMENT_OVERDUE' AND f.status='aguardando' THEN UPDATE public.financeiro_faturas SET status='vencida',atualizado_em=now() WHERE id=f.id; ELSIF _tipo='PAYMENT_DELETED' AND f.status IN ('aguardando','vencida') THEN UPDATE public.financeiro_faturas SET status='cancelada',observacoes=observacoes||E'\nCancelada no gateway',atualizado_em=now() WHERE id=f.id; ELSIF _tipo IN ('PAYMENT_REFUNDED','PAYMENT_CHARGEBACK') THEN UPDATE public.financeiro_pagamentos SET estornado=true,motivo_estorno='Estorno/devolução registrado pelo gateway' WHERE fatura_id=f.id AND NOT estornado; UPDATE public.financeiro_faturas SET status='estornada',atualizado_em=now() WHERE id=f.id; END IF; UPDATE public.financeiro_gateway_eventos SET processado=true WHERE evento_id=_evento_id; RETURN jsonb_build_object('ok',true); END; $$;
REVOKE ALL ON FUNCTION public.financeiro_webhook_processar(text,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.financeiro_webhook_processar(text,text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.financeiro_resumo() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE hoje date=(now() AT TIME ZONE 'America/Sao_Paulo')::date; BEGIN IF NOT private.financeiro_autorizado() THEN RAISE EXCEPTION 'Acesso financeiro não autorizado'; END IF; RETURN jsonb_build_object('hoje',hoje,'residentes',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'nome',nome_completo,'ativo',ativo,'responsavel',responsavel_principal_nome,'telefone',responsavel_principal_telefone) ORDER BY nome_completo),'[]') FROM public.residentes),'cadastros',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.financeiro_cadastros t),'catalogo',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY nome),'[]') FROM public.financeiro_catalogo t),'config',(SELECT to_jsonb(t) FROM public.financeiro_config t WHERE id),'cobrancas',(SELECT coalesce(jsonb_agg(to_jsonb(t)||jsonb_build_object('calculo',private.financeiro_saldo(t.id,hoje)) ORDER BY vencimento),'[]') FROM public.financeiro_cobrancas t),'itens',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.financeiro_itens t),'pagamentos',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY data DESC,criado_em DESC),'[]') FROM public.financeiro_pagamentos t),'alocacoes',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.financeiro_alocacoes t),'contatos',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY criado_em DESC),'[]') FROM public.financeiro_contatos t),'caixa',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.financeiro_caixa t),'faturas',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY criado_em DESC),'[]') FROM public.financeiro_faturas t),'faturaCobrancas',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.financeiro_fatura_cobrancas t),'auditoria',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY criado_em DESC),'[]') FROM (SELECT * FROM public.financeiro_auditoria ORDER BY criado_em DESC LIMIT 300) t)); END; $$;